{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울 시내 택시 승차대를 시가 금연구역으로 정할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시는 택시 승차대를 금연구역으로 지정할 수 있습니다. 조례 제5조제1항제7호는 시장이 금연구역으로 지정할 수 있는 장소로 「여객자동차 운수사업법 시행규칙」에 따른 시 관할 구역의 버스정류소 및 택시 승차대를 직접 정하고 있습니다.",
          "b_ids": "금연:제5조제1항, 금연:제5조제1항제7호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "택시 승차대를 금연구역으로 정할 때 구청장과의 협의가 반드시 필요한지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "택시 승차대를 금연구역으로 정할 때 구청장과의 협의는 반드시 해야 하는 것은 아닙니다. 조례 제5조제5항은 시장이 제1항제4호부터 제9호에 따라 금연구역을 지정할 때 필요하다고 인정하는 경우에 자치구청장과 협의할 수 있다고 정하고 있어, 협의는 의무사항이 아니라 재량사항입니다.",
          "b_ids": "금연:제5조제5항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
